SELECT CASE WHEN amount >= 1550 THEN 'high' WHEN amount >= 480 THEN 'mid' ELSE 'low' END AS amount_bucket, CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, COUNT(amount) AS amount_count, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS failed_count, MIN(paid_at) AS min_paid_at FROM payments GROUP BY amount_bucket, paid_cohort HAVING COUNT(CASE WHEN status = 'FAILED' THEN 1 END) >= 4 ORDER BY min_paid_at, amount_bucket, paid_cohort LIMIT 5;
